Section Tail3.
  Context {R : Type}.
  Variables (sp0 : word) (argv envp : list (list byte)) (cb : list byte) (D : list Z) (B : astate) (s1 : mstate).
  Hypothesis HII : II sp0 argv envp cb D B s1.
